/** Start Template Kit CSS: Indoor RockClimbing (css/customizer.css) **/

.envato-kit-111-skew .elementor-button-link,
.envato-kit-111-skew input,
.envato-kit-111-skew .elementor-button{
	transform: skew(-30deg);
}
.envato-kit-111-skew .elementor-button-text{
	transform: skew(30deg);
}

/** End Template Kit CSS: Indoor RockClimbing (css/customizer.css) **/

/** Start Template Kit CSS: Arts Festival (css/customizer.css) **/

/* Kit 94 Custom styles - applied under Advanced to the element they affect */
/* Large Hero Title Section */
.envato-kit-94-row{
	overflow-x: hidden;
}

.envato-kit-94-small-column .elementor-column-wrap{
	width: auto;
}
/* Large Buttons */
.envato-kit-94-button-full-width .elementor-button-link {
	width: 100%;
}
/* Equalize icons in icon list element */
.envato-kit-94-list-style-square .elementor-text-editor ul {
	list-style-type: square;
}

/** End Template Kit CSS: Arts Festival (css/customizer.css) **/

#bitnami-banner {z-index:100000;
	display:none; height:80px;padding:0px;width:120px;background:transparent;position:fixed;right:0px;bottom:0px;border:0px solid #EDEDED;} 

.meta-date{
	display:none
}
 .meta-author{
	display:none
} .meta-cat{
	display:none
} .meta-comments{
	display:none
}

